      return;
    }
    const t = setTimeout(() => setRestSec(s => s - 1), 1000);
    return () => clearTimeout(t);
  }, [isResting, restSec]);

  const startRest = useCallback((seconds = 60) => {
    if (seconds <= 0) return;
    setIsResting(true);
    setRestSec(seconds);
